
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_c_hltapw_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_c_hltapw", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-1.143200931164090e-01, -1.138467593569201e-01, -1.131673800884136e-01, -1.121933793919773e-01, -1.107994805802284e-01, -1.088101560536129e-01, -1.059829252519087e-01, -1.019899724096195e-01, -9.640564564782629e-02, -8.874151140367956e-02, -7.866250479877888e-02, -6.692173149243195e-02, -5.684108386673282e-02, -5.292775081648383e-02, -4.712746778927299e-02, -3.729473685001984e-02, -2.500218054863141e-02, -1.290888946865605e-02, -4.635284974267228e-03, -1.013444693505332e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


